 private void render(){if(destroyed)return;int y=scroll.getScrollY();list.removeAllViews();for(int i=0;i<2;i++)tabs.getChildAt(i).setBackground(rounded((guide?1:0)==i?0xff244e49:CARD,14));if(config==null){LinearLayout welcome=new LinearLayout(this);welcome.setOrientation(1);welcome.setPadding(dp(22),dp(26),dp(22),dp(26));welcome.setBackground(rounded(CARD,20));TextView heading=text("テレビを、手のひらに。",22,TEXT);heading.setTypeface(null,1);welcome.addView(heading);gap(welcome,12);welcome.addView(text("TVに表示した確認コードで、接続情報とチャンネルを取り込めます。",15,MUTED));gap(welcome,20);welcome.addView(button("TVに接続する",this::settings));list.addView(welcome);return;}TextView heading=text(guide?"番組表":"チャンネル",20,TEXT);heading.setTypeface(null,1);heading.setPadding(dp(2),dp(6),0,dp(12));list.addView(heading);SimpleDateFormat time=new SimpleDateFormat("MM/dd HH:mm",Locale.JAPAN);for(ChannelConfig.Channel ch:config.channels){ArrayList<TsEpg.Event> events=epg.forChannel(ch);if(guide){TextView name=text(ch.toString(),15,ACCENT);name.setPadding(dp(4),dp(18),0,dp(8));list.addView(name);if(events.isEmpty()){Button empty=button("番組情報はまだありません · この局を見る",()->tune(ch));list.addView(empty);continue;}int count=0;for(TsEpg.Event event:events){if(count++==8)break;LinearLayout card=card(false);card.addView(text(time.format(new Date(event.start)),11,ACCENT));gap(card,7);TextView nameView=text(event.title,15,TEXT);nameView.setTypeface(null,1);card.addView(nameView);gap(card,5);card.addView(text("番組詳細を見る  ›",11,MUTED));card.setOnClickListener(v->details(ch,event));addCard(card);}}else{boolean selected=current!=null&&current.key().equals(ch.key());LinearLayout card=card(selected);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView number=text(ch.display,23,selected?ACCENT:TEXT);number.setTypeface(null,1);row.addView(number,new LinearLayout.LayoutParams(dp(64),-2));LinearLayout labels=new LinearLayout(this);labels.setOrientation(1);TextView name=text(ch.name,15,TEXT);name.setTypeface(null,1);labels.addView(name);gap(labels,6);TextView programme=text(events.isEmpty()?"番組情報を受信すると表示します":events.get(0).title,12,MUTED);programme.setMaxLines(2);labels.addView(programme);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));row.addView(text(selected?"LIVE":"›",selected?10:24,ACCENT));card.addView(row);card.setOnClickListener(v->tune(ch));addCard(card);}}scroll.post(()->scroll.scrollTo(0,y));}
