 private void attachVideoOutput(){if(destroyed||player==null||surface==null||player.getVLCVout().areViewsAttached())return;player.getVLCVout().setVideoView(surface);player.getVLCVout().attachViews((vout,w,h,vw,vh,sn,sd)->{videoWidth=(sn>0&&sd>0)?(int)((long)vw*sn/sd):vw;videoHeight=vh;ui.post(this::resizeVideo);});surface.post(this::resizeVideo);}
 @Override protected void onResume(){super.onResume();attachVideoOutput();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)attachVideoOutput();}
 private void resizeVideo(){if(player==null||video==null)return;int w=video.getWidth(),h=video.getHeight();if(w<1||h<1)return;player.getVLCVout().setWindowSize(w,h);if(videoWidth>0&&videoHeight>0){double ratio=(double)videoWidth/videoHeight;int sw=w,sh=(int)(w/ratio);if(sh>h){sh=h;sw=(int)(h*ratio);}FrameLayout.LayoutParams old=(FrameLayout.LayoutParams)surface.getLayoutParams();if(old.width!=sw||old.height!=sh)surface.setLayoutParams(new FrameLayout.LayoutParams(Math.max(1,sw),Math.max(1,sh),Gravity.CENTER));}}
 private void details(ChannelConfig.Channel ch,TsEpg.Event event){SimpleDateFormat f=new SimpleDateFormat("MM/dd HH:mm",Locale.JAPAN);new AlertDialog.Builder(this).setTitle(event.title).setMessage(ch.toString()+"\n"+f.format(new Date(event.start))+" — "+f.format(new Date(event.end))+"\n\n"+(event.description.isEmpty()?"番組詳細はまだ取得していません":event.description)).setNegativeButton("閉じる",null).setPositiveButton("この局を見る",(d,w)->tune(ch)).show();}
 private void step(int n){if(config==null){settings();return;}int i=current==null?0:config.channels.indexOf(current);i=(i+n+config.channels.size())%config.channels.size();tune(config.channels.get(i));}
 private void clearConnection(){TvConnection c=connection;if(c!=null)c.cancel();StreamRelay r=relay;relay=null;if(r!=null)r.close();epg.resetAssembler();}
 private void stopAll(String message){generation.incrementAndGet();clearConnection();scanning=false;if(scanButton!=null)scanButton.setText("更新");if(player!=null)player.stop();if(overlay!=null){overlay.setText(message);overlay.setVisibility(View.VISIBLE);}if(status!=null)status.setText(message);audio.abandonAudioFocusRequest(focus);saveEpg();}
 private void tune(ChannelConfig.Channel ch){if(config==null||player==null){settings();return;}stopAll("選局しています…");int id=generation.get();ChannelConfig cfg=config;current=ch;currentName.setText(ch.toString());render();worker.execute(()->{if(id!=generation.get())return;try{TvConnection c=new TvConnection(cfg);connection=c;c.tune(ch);if(id!=generation.get())return;StreamRelay r=new StreamRelay(cfg,epg,msg->ui.post(()->{if(id==generation.get()&&!destroyed){status.setText(msg);overlay.setText("受信できませんでした");overlay.setVisibility(View.VISIBLE);}}));relay=r;r.start();ui.post(()->{if(id!=generation.get()||destroyed){r.close();return;}attachVideoOutput();audio.requestAudioFocus(focus);Media media=new Media(lib,Uri.parse(r.url()));media.setHWDecoderEnabled(getPreferences(0).getString("decoder","native").equals("native"),false);media.addOption(":program="+ch.sid);media.addOption(":network-caching=1200");player.setMedia(media);media.release();player.play();status.setText("放送データを読み込んでいます…");});}catch(Exception e){ui.post(()->{if(id==generation.get()&&!destroyed){String msg=e.getMessage();status.setText(msg==null?"TVへ接続できませんでした":msg);overlay.setText("別の局を選ぶか、接続設定を確認してください");overlay.setVisibility(View.VISIBLE);}});}});}
 private void scan(){if(config==null){settings();return;}new AlertDialog.Builder(this).setTitle("番組表を更新").setMessage("選択中のチューナーを順番に選局して番組情報を集めます。視聴は一時停止します。同じチューナーをPCで使用中の場合は、先にPC側を閉じてください。").setNegativeButton("戻る",null).setPositiveButton("取得する",(d,w)->scanNow()).show();}
 private void scanNow(){ChannelConfig.Channel previous=current;stopAll("番組表を取得しています…");scanning=true;guide=true;scanButton.setText("中止");int id=generation.get();ChannelConfig cfg=config;worker.execute(()->{LinkedHashMap<String,ChannelConfig.Channel> mux=new LinkedHashMap<>();for(ChannelConfig.Channel ch:cfg.channels)mux.putIfAbsent(ch.mux(),ch);int number=0,failed=0;for(ChannelConfig.Channel ch:mux.values()){if(id!=generation.get())return;int step=++number;ui.post(()->{if(id==generation.get())status.setText("番組表 "+step+" / "+mux.size()+" · "+ch.toString());});try{TvConnection c=new TvConnection(cfg);connection=c;c.tune(ch);if(id!=generation.get())return;StreamRelay r=new StreamRelay(cfg,epg,msg->{});relay=r;r.start();for(int i=0;i<80&&id==generation.get();i++)Thread.sleep(100);r.close();relay=null;epg.resetAssembler();}catch(Exception e){failed++;}if(id!=generation.get())return;}int misses=failed;ui.post(()->{if(id!=generation.get()||destroyed)return;scanning=false;scanButton.setText("更新");saveEpg();render();status.setText("番組情報 "+epg.snapshot().size()+"件を保存しました"+(misses>0?" · 未取得 "+misses+"多重":""));overlay.setText("番組表から局を選べます");if(previous!=null)tune(previous);});});}
