  Button search=button("近くのTVを探す · IPを自動入力",()->{});search.setOnClickListener(v->{if(discovery!=null)discovery.close();search.setEnabled(false);feedback.setText("接続を受け付けているTVを探しています…");discovery=new TvDiscovery(this,new TvDiscovery.Listener(){public void found(String address){if(destroyed)return;host.setText(address);search.setEnabled(true);feedback.setText("TVを見つけました。TVの確認コードを入力してください。");}public void failed(String message){if(destroyed)return;search.setEnabled(true);feedback.setText(message);}});discovery.start();});box.addView(search);gap(box,8);
